(() => {
  const style = document.createElement('style');
  style.textContent = `.work-actions{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}.work-actions button,.manager-message button{border:1px solid #b9d2c5;background:#fff;color:#166b49;border-radius:9px;padding:7px 12px;font:600 13px inherit;cursor:pointer}.work-actions button.active{background:#148457;color:#fff;border-color:#148457}.assignment.is-closed{opacity:.62}.assignment.is-closed h3{text-decoration:line-through}.manager-message textarea{width:100%;min-height:92px;resize:vertical;border:1px solid #cbd9d1;border-radius:10px;padding:11px;font:inherit;color:#193027;box-sizing:border-box}.message-actions{display:flex;align-items:center;gap:12px;margin-top:10px}.message-status{font-size:13px;color:#648072}.number-list{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:10px}.number-box{background:#f1f8f4;border-radius:12px;padding:13px}.number-box strong{display:block;font-size:25px;color:#136e4b}.number-box span{font-size:12px;color:#6d8177}`;
  document.head.appendChild(style);
  const cards = document.querySelector('.staff-grid');
  const assignments = [...document.querySelectorAll('.assignment')];
  const saved=JSON.parse(localStorage.getItem('bpoStaffTaskStates')||'{}');
  assignments.forEach((item,index) => { const actions=document.createElement('div'); actions.className='work-actions'; actions.innerHTML='<button class="active" type="button">Open</button><button type="button">Close</button><span class="task-status" aria-live="polite"></span>'; const [open,close]=actions.querySelectorAll('button'),status=actions.querySelector('.task-status'); const setState=(closed)=>{item.classList.toggle('is-closed',closed);open.classList.toggle('active',!closed);close.classList.toggle('active',closed);status.textContent=closed?'Completed':'In progress';saved[index]=closed?'closed':'open';localStorage.setItem('bpoStaffTaskStates',JSON.stringify(saved));update()}; open.onclick=()=>setState(false); close.onclick=()=>setState(true); item.appendChild(actions); setState(saved[index]==='closed'); });
  const numbers=document.createElement('article'); numbers.className='staff-card2'; numbers.innerHTML='<h2>Work numbers</h2><div class="number-list"><div class="number-box"><strong id="open-work-count">3</strong><span>Open assignments</span></div><div class="number-box"><strong id="closed-work-count">0</strong><span>Closed assignments</span></div><div class="number-box"><strong>15</strong><span>Calls completed</span></div><div class="number-box"><strong>9</strong><span>Calls remaining</span></div></div>'; cards?.appendChild(numbers);
  const manager=document.createElement('article'); manager.className='staff-card2 manager-message'; manager.innerHTML='<h2>Message your manager</h2><p class="muted">Share a blocker, update, or request before your shift ends.</p><textarea aria-label="Message for manager" placeholder="Write a message for your manager..."></textarea><div class="message-actions"><button type="button">Send message</button><span class="message-status" aria-live="polite"></span></div>'; manager.querySelector('button').onclick=()=>{const box=manager.querySelector('textarea'),status=manager.querySelector('.message-status'); status.textContent=box.value.trim()?'Message saved for your manager.':'Write a message first.'; if(box.value.trim()) box.value='';}; cards?.appendChild(manager);
  function update(){const open=assignments.filter(x=>!x.classList.contains('is-closed')).length; document.getElementById('open-work-count').textContent=open; document.getElementById('closed-work-count').textContent=assignments.length-open;}
})();
